def run_code(api_key, request_payload, sandbox_id=None, runtime=None, region=None, image=None, cpu_millicores=None, memory_mb=None, ttl_seconds=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0355000" if __import__("os").path.isdir("./environment_mix/0355000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    endpoint = "run_code"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _day_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        # Use uuid4 to ensure uniqueness; keep vendor-like prefix.
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, list):
            return data
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"]
        return []

    def _save_rows(filename, rows):
        _save(filename, rows)

    def _log(api_key_id, workspace_id, status_s, error=None):
        # Observable dynamics: record every call
        req = _load_rows("request_log.json")
        latency_ms = int((time.time() - t0) * 1000)
        req.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_s,
            "error": error,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        })
        _save_rows("request_log.json", req)

    # ---- Validate inputs (relax overly-strict patterns: datastore ids are 01J..., not 01H8...) ----
    if not isinstance(api_key, str) or not api_key:
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(request_payload, dict):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "request_payload must be an object.")
    if sandbox_id is not None and (not isinstance(sandbox_id, str) or not sandbox_id):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sandbox_id must be a string.")
    allowed_runtime = {"python", "node", "bash", "container"}
    allowed_region = {"us-east-1", "us-west-2", "eu-west-1", "ap-southeast-1"}
    if runtime is not None and (not isinstance(runtime, str) or runtime not in allowed_runtime):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid runtime; must be one of python|node|bash|container.")
    if region is not None and (not isinstance(region, str) or region not in allowed_region):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid region.")
    if image is not None and not isinstance(image, str):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "image must be a string.")
    if cpu_millicores is not None and (not isinstance(cpu_millicores, int) or cpu_millicores < 1):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cpu_millicores must be an integer >= 1.")
    if memory_mb is not None and (not isinstance(memory_mb, int) or memory_mb < 1):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "memory_mb must be an integer >= 1.")
    if ttl_seconds is not None and (not isinstance(ttl_seconds, int) or ttl_seconds < 1):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "ttl_seconds must be an integer >= 1.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key):
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")

    # ---- Authenticate (match by id, else by prefix) ----
    api_keys = _load_rows("api_keys.json")
    workspaces = _load_rows("workspaces.json")
    sandboxes = _load_rows("sandboxes.json")
    executions = _load_rows("executions.json")
    usage = _load_rows("usage_ledger.json")

    key_row = None
    # Prefer exact id match
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        # fallback: prefix match
        for r in api_keys:
            if isinstance(r, dict) and r.get("prefix") == api_key:
                key_row = r
                break
    if key_row is None:
        _log(None, None, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key not found.")
    if key_row.get("status") != "active":
        _log(key_row.get("id"), key_row.get("workspace_id"), "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is revoked.")

    ws_id = key_row.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if ws is None:
        _log(key_row.get("id"), ws_id, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace not found for API key.")
    if ws.get("status") != "active":
        _log(key_row.get("id"), ws_id, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Update last_used_at on successful auth (persist)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save_rows("api_keys.json", api_keys)

    # ---- Daily quota enforcement based on finalized usage (rule: reject subsequent run_code if exceeds any daily quota) ----
    bucket = _day_bucket(now)
    bucket_iso = bucket.isoformat().replace("+00:00", "Z")

    # Find or create open ledger row for today (finalized rows immutable)
    ledger_row = None
    for r in usage:
        if isinstance(r, dict) and r.get("workspace_id") == ws_id:
            udt = _parse_dt(r.get("usage_date"))
            if udt is not None and _day_bucket(udt) == bucket:
                ledger_row = r
                break
    if ledger_row is None:
        ledger_row = {
            "id": _gen_id("e2b_use"),
            "workspace_id": ws_id,
            "usage_date": bucket_iso,
            "sandboxes_created": 0,
            "cpu_ms": 0,
            "memory_mb_s": 0,
            "network_egress_mb": 0,
            "status": "open",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ledger_row)
        _save_rows("usage_ledger.json", usage)

    # If already over quota today, block
    try:
        if int(ledger_row.get("cpu_ms") or 0) > int(ws.get("quota_cpu_ms_per_day") or 0) or \
           int(ledger_row.get("memory_mb_s") or 0) > int(ws.get("quota_memory_mb_s_per_day") or 0) or \
           int(ledger_row.get("network_egress_mb") or 0) > int(ws.get("quota_network_egress_mb_per_day") or 0):
            _log(key_row.get("id"), ws_id, "error", {"code": "QUOTA_EXCEEDED"})
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this workspace; try again after the next UTC day bucket.")
    except Exception:
        # If parsing quota fields fails, treat as validation/config issue (server-side). Return a safe error.
        _log(key_row.get("id"), ws_id, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Workspace quota configuration is invalid.")

    # ---- Idempotency ----
    if idempotency_key is not None:
        existing = None
        for e in executions:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("idempotency_key") == idempotency_key:
                existing = e
                break
        if existing is not None:
            # Return persisted response (no new sandbox provisioned)
            resp = existing.get("response_payload") if isinstance(existing.get("response_payload"), dict) else {}
            _log(key_row.get("id"), ws_id, "ok", None)
            return {
                "data": {
                    "execution": existing,
                    "response": resp,
                    "sandbox_id": existing.get("sandbox_id"),
                    "idempotency_key": idempotency_key,
                    "deduped": True,
                }
            }

    # ---- Resolve/validate sandbox ----
    sbx = None
    provision_new = False
    if sandbox_id is not None:
        sbx = next((s for s in sandboxes if isinstance(s, dict) and s.get("id") == sandbox_id), None)
        if sbx is None:
            _log(key_row.get("id"), ws_id, "error", {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Sandbox not found.")
        if sbx.get("workspace_id") != ws_id:
            _log(key_row.get("id"), ws_id, "error", {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Sandbox is not accessible in this workspace.")
        # sandbox may be terminated/failed/expired -> cannot run in it
        if sbx.get("status") not in ("provisioning", "running"):
            _log(key_row.get("id"), ws_id, "error", {"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Cannot run code in a sandbox that is not provisioning/running.")
    else:
        provision_new = True

    # When provisioning, require runtime & region; set defaults for resources if omitted but validate against schema constraints
    if provision_new:
        if runtime is None or region is None:
            _log(key_row.get("id"), ws_id, "error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "runtime and region are required when provisioning a new sandbox.")
        # Apply sane defaults if not provided
        if cpu_millicores is None:
            cpu_millicores = 250
        if memory_mb is None:
            memory_mb = 512
        if ttl_seconds is None:
            ttl_seconds = 900

        # Enforce schema constraints
        if not (50 <= int(cpu_millicores) <= 16000):
            _log(key_row.get("id"), ws_id, "error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cpu_millicores must be between 50 and 16000.")
        if not (64 <= int(memory_mb) <= 65536):
            _log(key_row.get("id"), ws_id, "error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "memory_mb must be between 64 and 65536.")
        if not (10 <= int(ttl_seconds) <= 86400):
            _log(key_row.get("id"), ws_id, "error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "ttl_seconds must be between 10 and 86400.")

        # Concurrent quota
        concurrent = sum(1 for s in sandboxes if isinstance(s, dict) and s.get("workspace_id") == ws_id and s.get("status") in ("provisioning", "running"))
        if concurrent >= int(ws.get("quota_concurrent_sandboxes") or 0):
            _log(key_row.get("id"), ws_id, "error", {"code": "QUOTA_EXCEEDED"})
            return _err("QUOTA_EXCEEDED", "Concurrent sandbox quota exceeded for this workspace.")

        # Rate limit: sandboxes created within last 60 seconds
        limit_per_min = int(ws.get("quota_sandboxes_per_minute") or 0)
        if limit_per_min == 0:
            # If quota is 0, never allow provisioning new sandbox
            _log(key_row.get("id"), ws_id, "error", {"code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Sandbox creation rate limit reached for this workspace.")
        window_start = now - datetime.timedelta(seconds=60)
        created_last_min = 0
        for s in sandboxes:
            if not isinstance(s, dict) or s.get("workspace_id") != ws_id:
                continue
            cdt = _parse_dt(s.get("created_at"))
            if cdt is not None and cdt >= window_start:
                created_last_min += 1
        if created_last_min >= limit_per_min:
            _log(key_row.get("id"), ws_id, "error", {"code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Sandbox creation rate limit reached for this workspace (quota_sandboxes_per_minute).")

        # Create sandbox in provisioning then running (legal transition provisioning->running)
        sbx = {
            "id": _gen_id("e2b_sbx"),
            "workspace_id": ws_id,
            "api_key_id": key_row.get("id"),
            "status": "provisioning",
            "runtime": runtime,
            "region": region,
            "image": image,
            "cpu_millicores": int(cpu_millicores),
            "memory_mb": int(memory_mb),
            "ttl_seconds": int(ttl_seconds),
            "started_at": None,
            "terminated_at": None,
            "last_heartbeat_at": None,
            "exit_code": None,
            "failure_reason": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sandboxes.append(sbx)

        # Increment sandboxes_created in today's ledger if ledger is open; finalized immutable
        if ledger_row.get("status") == "finalized":
            _log(key_row.get("id"), ws_id, "error", {"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Usage ledger for today is finalized and immutable; cannot record new usage.")
        ledger_row["sandboxes_created"] = int(ledger_row.get("sandboxes_created") or 0) + 1
        ledger_row["updated_at"] = now_iso

        # Transition sandbox to running (provisioning->running); set started_at
        sbx["status"] = "running"
        sbx["started_at"] = now_iso
        sbx["updated_at"] = now_iso

        _save_rows("sandboxes.json", sandboxes)
        _save_rows("usage_ledger.json", usage)

    # ---- Create execution row and run lifecycle queued->running->succeeded ----
    exe = {
        "id": _gen_id("e2b_exe"),
        "workspace_id": ws_id,
        "api_key_id": key_row.get("id"),
        "sandbox_id": sbx.get("id") if isinstance(sbx, dict) else None,
        "status": "queued",
        "request_payload": {},  # business rule: normalized empty object for this tool surface
        "response_payload": None,
        "error": None,
        "duration_ms": None,
        "cpu_ms": 0,
        "memory_mb_s": 0,
        "network_egress_mb": 0,
        "idempotency_key": idempotency_key,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    executions.append(exe)
    _save_rows("executions.json", executions)

    # Move to running
    exe["status"] = "running"
    exe["updated_at"] = now_iso

    # Simulated completion (since offline): succeed with minimal deterministic metrics
    # Metrics must be finalized and added to usage_ledger on completion.
    # Use small non-zero values but keep within integer.
    cpu_used = max(1, int((cpu_millicores or sbx.get("cpu_millicores") or 250)) // 10)
    dur_ms = max(1, int((time.time() - t0) * 1000))
    mem_mb_s_used = max(1, int((memory_mb or sbx.get("memory_mb") or 512) * max(dur_ms, 1) / 1000))
    net_used = 0

    # Before finalizing usage, ensure ledger is open and quotas won't be exceeded by adding this execution.
    if ledger_row.get("status") == "finalized":
        exe["status"] = "failed"
        exe["error"] = {"code": "INVALID_TRANSITION", "message": "Usage ledger for today is finalized; cannot record usage."}
        exe["duration_ms"] = dur_ms
        exe["cpu_ms"] = 0
        exe["memory_mb_s"] = 0
        exe["network_egress_mb"] = 0
        exe["updated_at"] = now_iso
        exe["response_payload"] = {"ok": False}
        _save_rows("executions.json", executions)
        _log(key_row.get("id"), ws_id, "error", {"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Usage ledger for today is finalized and immutable; cannot record new usage.")

    new_cpu = int(ledger_row.get("cpu_ms") or 0) + int(cpu_used)
    new_mem = int(ledger_row.get("memory_mb_s") or 0) + int(mem_mb_s_used)
    new_net = int(ledger_row.get("network_egress_mb") or 0) + int(net_used)

    if new_cpu > int(ws.get("quota_cpu_ms_per_day") or 0) or new_mem > int(ws.get("quota_memory_mb_s_per_day") or 0) or new_net > int(ws.get("quota_network_egress_mb_per_day") or 0):
        # Reject completion as failed and do not apply usage increments; subsequent calls will also be rejected by snapshot check.
        exe["status"] = "failed"
        exe["error"] = {"code": "QUOTA_EXCEEDED", "message": "Daily usage quota would be exceeded by this execution."}
        exe["duration_ms"] = dur_ms
        exe["cpu_ms"] = 0
        exe["memory_mb_s"] = 0
        exe["network_egress_mb"] = 0
        exe["updated_at"] = now_iso
        exe["response_payload"] = {"ok": False}
        _save_rows("executions.json", executions)
        _log(key_row.get("id"), ws_id, "error", {"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily usage quota exceeded for this workspace; try again after the next UTC day bucket.")

    # Apply usage and mark execution succeeded
    ledger_row["cpu_ms"] = new_cpu
    ledger_row["memory_mb_s"] = new_mem
    ledger_row["network_egress_mb"] = new_net
    ledger_row["updated_at"] = now_iso
    _save_rows("usage_ledger.json", usage)

    exe["status"] = "succeeded"
    exe["duration_ms"] = dur_ms
    exe["cpu_ms"] = int(cpu_used)
    exe["memory_mb_s"] = int(mem_mb_s_used)
    exe["network_egress_mb"] = int(net_used)
    exe["response_payload"] = {
        "ok": True,
        "result": "completed",
        "sandbox_id": exe.get("sandbox_id"),
    }
    exe["updated_at"] = now_iso
    _save_rows("executions.json", executions)

    _log(key_row.get("id"), ws_id, "ok", None)
    return {
        "data": {
            "execution": exe,
            "response": exe.get("response_payload") or {},
            "sandbox_id": exe.get("sandbox_id"),
            "idempotency_key": idempotency_key,
            "deduped": False,
        }
    }

def get_me(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0355000" if __import__("os").path.isdir("./environment_mix/0355000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")
    endpoint = "get_me"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _day_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, list):
            return data
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"]
        return []

    def _save_rows(filename, rows):
        _save(filename, rows)

    def _log(api_key_id, workspace_id, status_s, error=None):
        req = _load_rows("request_log.json")
        latency_ms = int((time.time() - t0) * 1000)
        req.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_s,
            "error": error,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        })
        _save_rows("request_log.json", req)

    if not isinstance(api_key, str) or not api_key:
        _log(None, None, "error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    workspaces = _load_rows("workspaces.json")
    api_keys = _load_rows("api_keys.json")
    sandboxes = _load_rows("sandboxes.json")
    usage = _load_rows("usage_ledger.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if key_row is None:
        key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("prefix") == api_key), None)
    if not key_row:
        _log(None, None, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key not found.")
    if key_row.get("status") != "active":
        _log(key_row.get("id"), key_row.get("workspace_id"), "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is revoked.")

    ws_id = key_row.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws:
        _log(key_row.get("id"), ws_id, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace not found for API key.")
    if ws.get("status") != "active":
        _log(key_row.get("id"), ws_id, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Update last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save_rows("api_keys.json", api_keys)

    # Usage snapshot for today
    bucket = _day_bucket(now)
    ledger_row = None
    for r in usage:
        if isinstance(r, dict) and r.get("workspace_id") == ws_id:
            udt = _parse_dt(r.get("usage_date"))
            if udt is not None and _day_bucket(udt) == bucket:
                ledger_row = r
                break

    usage_snapshot = {
        "usage_date": bucket.isoformat().replace("+00:00", "Z"),
        "sandboxes_created": int((ledger_row or {}).get("sandboxes_created") or 0),
        "cpu_ms": int((ledger_row or {}).get("cpu_ms") or 0),
        "memory_mb_s": int((ledger_row or {}).get("memory_mb_s") or 0),
        "network_egress_mb": int((ledger_row or {}).get("network_egress_mb") or 0),
        "status": (ledger_row or {}).get("status") or "open",
    }

    concurrent = sum(1 for s in sandboxes if isinstance(s, dict) and s.get("workspace_id") == ws_id and s.get("status") in ("provisioning", "running"))

    _log(key_row.get("id"), ws_id, "ok", None)
    return {
        "data": {
            "api_key": {
                "id": key_row.get("id"),
                "name": key_row.get("name"),
