        rows = [s for s in rows if _created_dt(s) >= dt_after]
    if dt_before is not None:
        rows = [s for s in rows if _created_dt(s) < dt_before]

    reverse = (sort == "created_at_desc")
    rows.sort(key=_created_dt, reverse=reverse)

